// .lavish-wip/m3-md/check-anchors.mjs
// A DOCUMENTATION-CONSISTENCY CHECKER, not a test.
// AGENTS.md bans source-grep *tests* — a test that reads an implementation file and
// asserts on its text. This reads the back matter WE wrote, resolves the citations in
// it, and asserts nothing about any code's behaviour. It lives outside packages/*/test/
// on purpose. It is the cheapest guard against the exact failure this spec found 13 times:
// a file:line that no longer says what the document claims it says.
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative, resolve } from "node:path";

const REPO = resolve(import.meta.dir, "../..");
const DIR = import.meta.dir;
const MD_FILES = ["90-back1.md", "90-back2.md", "90-back3.md"].map(f => join(DIR, f));

// `path/to/file.ts:123`  or  `path/to/file.ts:12-18`
const ANCHOR = /`([A-Za-z0-9_@./-]+\.(?:ts|tsx|js|mjs|json|py|md|kdl|rs|yml|yaml|txt))`?\s*:(\d+)(?:-(\d+))?`/g;
// <!-- assert: <path> <line> <literal> -->
const ASSERT = /^<!--\s*assert:\s*(\S+)\s+(\d+)\s+(.+?)\s*-->$/gm;

const problems = [];
let checked = 0;

function lineCount(path) {
	try {
		return readFileSync(path, "utf8").split("\n").length;
	} catch {
		return null;
	}
}

for (const md of MD_FILES) {
	let text;
	try {
		text = readFileSync(md, "utf8");
	} catch {
		problems.push(`${relative(REPO, md)}: missing`);
		continue;
	}

	for (const m of text.matchAll(ANCHOR)) {
		const [, rel, startRaw, endRaw] = m;
		const start = Number(startRaw);
		const end = endRaw ? Number(endRaw) : start;
		checked++;
		const abs = join(REPO, rel);
		if (!statSync(abs, { throwIfNoEntry: false })) {
			problems.push(`${relative(REPO, md)}: ${rel}:${startRaw} — no such file`);
			continue;
		}
		const n = lineCount(abs);
		if (n !== null && end > n) {
			problems.push(`${relative(REPO, md)}: ${rel}:${startRaw}${endRaw ? `-${endRaw}` : ""} — past EOF (${n} lines)`);
		}
	}

	for (const m of text.matchAll(ASSERT)) {
		const [, rel, lineRaw, literal] = m;
		checked++;
		const abs = join(REPO, rel);
		const lines = readFileSync(abs, "utf8").split("\n");
		const idx = Number(lineRaw) - 1;
		if (idx >= lines.length) {
			problems.push(`${relative(REPO, md)}: assert ${rel}:${lineRaw} — past EOF (${lines.length} lines)`);
		} else if (!lines[idx].includes(literal)) {
			problems.push(`${relative(REPO, md)}: assert ${rel}:${lineRaw} — expected ${JSON.stringify(literal)}`);
		}
	}
}

for (const p of problems) console.log(`FAIL ${p}`);
console.log(`${checked} anchors checked, ${problems.length} problem(s)`);
if (problems.length) process.exit(1);
